-- Synthetic fixtures only. Every write is rolled back. TEST project only.
BEGIN;
SET LOCAL ROLE service_role;
DO $$
DECLARE s uuid; r uuid; r2 uuid; a uuid; b uuid; c uuid; other_item uuid; dossier uuid; second_dossier uuid; line_id uuid; blocked boolean; v integer; base_count integer;
BEGIN
  INSERT INTO public.refurb_suppliers(name) VALUES('TEST RMA VERIFICATION') RETURNING id INTO s;
  INSERT INTO public.refurb_receptions(reception_number,reception_date,supplier,supplier_id,vat_scheme,supplier_invoice_nr) VALUES('TEST-RMA-'||gen_random_uuid(),current_date,'TEST RMA VERIFICATION',s,'margin','TEST-ONLY') RETURNING id INTO r;
  INSERT INTO public.refurb_receptions(reception_number,reception_date,supplier,vat_scheme,supplier_invoice_nr) VALUES('TEST-RMA-'||gen_random_uuid(),current_date,'OTHER TEST SUPPLIER','margin','TEST-ONLY') RETURNING id INTO r2;
  INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,price_cents) VALUES(r,0,'New',10000) RETURNING id INTO a;
  UPDATE public.refurb_reception_items SET refurb_status='RMA' WHERE id=a;
  IF NOT EXISTS(SELECT 1 FROM public.refurb_reception_items WHERE id=a AND compensation_cents=10000 AND rma_registered) THEN RAISE EXCEPTION 'Automatic price compensation failed'; END IF;
  UPDATE public.refurb_reception_items SET compensation_cents=7500 WHERE id=a;
  UPDATE public.refurb_reception_items SET refurb_status='RMA Submitted' WHERE id=a;
  IF NOT EXISTS(SELECT 1 FROM public.refurb_reception_items WHERE id=a AND compensation_cents=7500 AND rma_registered) THEN RAISE EXCEPTION 'Manual compensation lost'; END IF;
  UPDATE public.refurb_reception_items SET refurb_status='Battery',compensation_cents=NULL,rma_registered=false WHERE id=a;
  IF NOT EXISTS(SELECT 1 FROM public.refurb_reception_items WHERE id=a AND rma_registered) THEN RAISE EXCEPTION 'RMA history flag lost'; END IF;
  UPDATE public.refurb_reception_items SET refurb_status='RMA' WHERE id=a;
  UPDATE public.refurb_reception_items SET compensation_cents=0 WHERE id=a;
  UPDATE public.refurb_reception_items SET refurb_status='RMA Supplier' WHERE id=a;
  UPDATE public.refurb_reception_items SET refurb_status='RMA' WHERE id=a;
  IF NOT EXISTS(SELECT 1 FROM public.refurb_reception_items WHERE id=a AND compensation_cents=0) THEN RAISE EXCEPTION 'Manual zero overwritten'; END IF;
  INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,price_cents) VALUES(r,1,'RMA',20000) RETURNING id INTO b;
  INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,price_cents) VALUES(r,2,'RMA',NULL) RETURNING id INTO c;
  IF NOT EXISTS(SELECT 1 FROM public.refurb_reception_items WHERE id=c AND compensation_cents IS NULL AND rma_registered) THEN RAISE EXCEPTION 'Missing price treated as zero'; END IF;
  INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,price_cents) VALUES(r2,0,'RMA',10000) RETURNING id INTO other_item;
  dossier:=public.manage_supplier_rma('create',jsonb_build_object('supplier_id',s,'supplier_name','TEST RMA VERIFICATION','item_ids',jsonb_build_array(a,b)), 'test@example.invalid');
  IF (SELECT count(*) FROM public.supplier_rma_items WHERE case_id=dossier)<>2 THEN RAISE EXCEPTION 'Case items not atomically attached'; END IF;
  IF (SELECT sum(expected_cents) FROM public.supplier_rma_items WHERE case_id=dossier)<>20000 THEN RAISE EXCEPTION 'Expected values did not preserve zero'; END IF;
  SELECT version INTO v FROM public.supplier_rma_cases WHERE id=dossier;
  SELECT id INTO line_id FROM public.supplier_rma_items WHERE case_id=dossier AND reception_item_id=b;
  PERFORM public.manage_supplier_rma('update_item',jsonb_build_object('case_id',dossier,'version',v,'item_id',line_id,'expected_cents',18000,'received_cents',5000,'notes','TEST partial payment'), 'test@example.invalid');
  IF NOT EXISTS(SELECT 1 FROM public.supplier_rma_items WHERE id=line_id AND expected_cents=18000 AND received_cents=5000) THEN RAISE EXCEPTION 'Partial receipt failed'; END IF;
  blocked:=false; BEGIN PERFORM public.manage_supplier_rma('update_item',jsonb_build_object('case_id',dossier,'version',v,'item_id',line_id,'expected_cents',1,'received_cents',0), 'test@example.invalid'); EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_CONFLICT' THEN blocked:=true; ELSE RAISE; END IF; END;
  IF NOT blocked THEN RAISE EXCEPTION 'Stale update accepted'; END IF;
  SELECT version INTO v FROM public.supplier_rma_cases WHERE id=dossier;
  blocked:=false; BEGIN PERFORM public.manage_supplier_rma('add_items',jsonb_build_object('case_id',dossier,'version',v,'item_ids',jsonb_build_array(other_item)), 'test@example.invalid'); EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_SUPPLIER_MISMATCH' THEN blocked:=true; ELSE RAISE; END IF; END;
  IF NOT blocked THEN RAISE EXCEPTION 'Mixed suppliers accepted'; END IF;
  blocked:=false; BEGIN PERFORM public.manage_supplier_rma('create',jsonb_build_object('supplier_id',s,'supplier_name','TEST RMA VERIFICATION','item_ids',jsonb_build_array(a)), 'test@example.invalid'); EXCEPTION WHEN unique_violation THEN blocked:=true; END;
  IF NOT blocked THEN RAISE EXCEPTION 'Duplicate active case accepted'; END IF;
  PERFORM public.manage_supplier_rma('update_case',jsonb_build_object('case_id',dossier,'version',v,'stage','closed'), 'test@example.invalid');
  IF EXISTS(SELECT 1 FROM public.supplier_rma_items WHERE case_id=dossier AND active) THEN RAISE EXCEPTION 'Closed case still active'; END IF;
  SELECT version INTO v FROM public.supplier_rma_cases WHERE id=dossier;
  blocked:=false; BEGIN PERFORM public.manage_supplier_rma('update_item',jsonb_build_object('case_id',dossier,'version',v,'item_id',line_id,'expected_cents',1,'received_cents',0), 'test@example.invalid'); EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_CASE_CLOSED' THEN blocked:=true; ELSE RAISE; END IF; END;
  IF NOT blocked THEN RAISE EXCEPTION 'Closed item edited'; END IF;
  second_dossier:=public.manage_supplier_rma('create',jsonb_build_object('supplier_id',s,'supplier_name','TEST RMA VERIFICATION','item_ids',jsonb_build_array(a)), 'test@example.invalid');
  blocked:=false; BEGIN PERFORM public.manage_supplier_rma('update_case',jsonb_build_object('case_id',dossier,'version',v,'stage','draft'), 'test@example.invalid'); EXCEPTION WHEN unique_violation THEN blocked:=true; END;
  IF NOT blocked OR NOT EXISTS(SELECT 1 FROM public.supplier_rma_cases WHERE id=dossier AND stage='closed') THEN RAISE EXCEPTION 'Reopen conflict was not atomic'; END IF;
  IF (SELECT count(*) FROM public.supplier_rma_history WHERE case_id=dossier)<>3 THEN RAISE EXCEPTION 'Audit events missing or failed events recorded'; END IF;
  IF (SELECT count(*) FROM public.supplier_rma_status_history WHERE reception_item_id=a)<5 THEN RAISE EXCEPTION 'Source history missing'; END IF;
END $$;
ROLLBACK;
SELECT 'PASS: auto compensation, overrides, once RMA always RMA, dossiers, receipts, conflicts, audit; all fixtures rolled back' AS verification;
